using System.IO;
using System.Linq;
using System.Threading;
using Silo.Drawio;
using Telefrag.DI;

namespace Silo.Tools;

/// <summary>
///     A live diagram of the model: a box for every open Silo and for each of its connections, with the connecting
///     edge labeled by connector name. It is rendered by an embedded draw.io (see <see cref="DrawioView" />) using the
///     read-only <see cref="DrawioProfiles.ModelReadOnly" /> profile and generated by <see cref="SiloModelDiagramSource" />,
///     so it follows the model as Silos open and close and as connections change state. Clicking a box activates that
///     Silo or connection.
/// </summary>
/// <remarks>
///     The profile is the lock: what a person may do in this pane (and what is hidden) is set by the profile's
///     options, editable via Ctrl+right-click -> "Diagram options..." at Author level. Registered as a singleton so the
///     pane (and its web view) is built once and reused.
/// </remarks>
[Singleton(typeof(ITool))]
public class ConnectionDiagramTool : ToolBase
{
    private DrawioView? _view;

    public ConnectionDiagramTool() : base("connectiondiagram")
    {
        DisplayName = "Connection Diagram";
        GroupName   = "Diagrams";
    }

    protected override UIElement OnBuildContent()
    {
        _view = new DrawioView(DrawioProfiles.ModelReadOnly)
                {
                    Source = new SiloModelDiagramSource()
                };

        DrawioDesign.Attach(_view, _view);
        return _view;
    }
}
